      "mergeDaily": true,
      "data": {
        "EN": {
          "entrance": {
            "text": "Peter the Apostle, and Paul the teacher of the Gentiles, these have taught us your law, O Lord.",
            "lines": [
              {
                "sp": "",
                "text": "Peter the Apostle, and Paul the teacher of the Gentiles, these have taught us your law, O Lord."
              }
            ]
          },
          "collect": {
            "text": "Grant, we pray, O Lord our God, that we may be sustained by the intercession of the blessed Apostles Peter and Paul, that, as through them you gave your Church the foundations of her heavenly office, so through them you may help her to eternal salvation. Through our Lord Jesus Christ, your Son, who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever.",
            "lines": [
              {
                "sp": "",
                "text": "Grant, we pray, O Lord our God, that we may be sustained by the intercession of the blessed Apostles Peter and Paul, that, as through them you gave your Church the foundations of her heavenly office, so through them you may help her to eternal salvation. Through our Lord Jesus Christ, your Son, who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever."
              }
            ]
          },
          "prayer_offerings": {
            "text": "We bring offerings to your altar, O Lord, as we glory in the solemn feast of the blessed Apostles Peter and Paul, so that the more we doubt our own merits, the more we may rejoice that we are to be saved by your loving kindness. Through Christ our Lord.",
            "lines": [
              {
                "sp": "",
                "text": "We bring offerings to your altar, O Lord, as we glory in the solemn feast of the blessed Apostles Peter and Paul, so that the more we doubt our own merits, the more we may rejoice that we are to be saved by your loving kindness. Through Christ our Lord."
              }
            ]
          },
          "communion": {
            "text": "Simon, Son of John, do you love me more than these? Lord, you know everything; you know that I love you.",
            "lines": [
              {
                "sp": "",
                "text": "Simon, Son of John, do you love me more than these? Lord, you know everything; you know that I love you."
              }
            ]
          },
          "prayer_after": {
            "text": "By this heavenly Sacrament, O Lord, we pray, strengthen your faithful, whom you have enlightened with the teaching of the Apostles. Through Christ our Lord.",
            "lines": [
              {
                "sp": "",
                "text": "By this heavenly Sacrament, O Lord, we pray, strengthen your faithful, whom you have enlightened with the teaching of the Apostles. Through Christ our Lord."
              }
            ]
          }
        }
      },
