      "mergeDaily": true,
      "data": {
        "EN": {
          "entrance": {
            "text": "He will be great in the sight of the Lord and will be filled with the Holy Spirit, even from his mother’s womb; and many will rejoice at his birth.",
            "lines": [
              {
                "sp": "",
                "text": "He will be great in the sight of the Lord and will be filled with the Holy Spirit, even from his mother’s womb; and many will rejoice at his birth."
              }
            ]
          },
          "collect": {
            "text": "Grant, we pray, almighty God, that your family may walk in the way of salvation and, attentive to what Saint John the Precursor urged, may come safely to the One he foretold, our Lord Jesus Christ. Who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever.",
            "lines": [
              {
                "sp": "",
                "text": "Grant, we pray, almighty God, that your family may walk in the way of salvation and, attentive to what Saint John the Precursor urged, may come safely to the One he foretold, our Lord Jesus Christ. Who lives and reigns with you in the unity of the Holy Spirit, one God, for ever and ever."
              }
            ]
          },
          "prayer_offerings": {
            "text": "Look with favor, O Lord, upon the offerings made by your people on the Solemnity of Saint John the Baptist, and grant that what we celebrate in mystery we may follow with deeds of devoted service. Through Christ our Lord.",
            "lines": [
              {
                "sp": "",
                "text": "Look with favor, O Lord, upon the offerings made by your people on the Solemnity of Saint John the Baptist, and grant that what we celebrate in mystery we may follow with deeds of devoted service. Through Christ our Lord."
              }
            ]
          },
          "communion": {
            "text": "Blessed be the Lord, the God of Israel! He has visited his people and redeemed them.",
            "lines": [
              {
                "sp": "",
                "text": "Blessed be the Lord, the God of Israel! He has visited his people and redeemed them."
              }
            ]
          },
          "prayer_after": {
            "text": "May the marvelous prayer of Saint John the Baptist accompany us who have eaten our fill at this sacrificial feast, O Lord, and, since Saint John proclaimed your Son to be the Lamb who would take away our sins, may he implore now for us your favor. Through Christ our Lord.",
            "lines": [
              {
                "sp": "",
                "text": "May the marvelous prayer of Saint John the Baptist accompany us who have eaten our fill at this sacrificial feast, O Lord, and, since Saint John proclaimed your Son to be the Lamb who would take away our sins, may he implore now for us your favor. Through Christ our Lord."
              }
            ]
          }
        }
      },
